 double upper=initial;for(const char *table:{"preset","custom"})if(expressions.contains(table))for(const auto &e:expressions[table]){double delta=0;for(const auto &bind:e.value("materialColorBinds",nlohmann::json::array()))if(bind["material"]==object.appearance->source_material&&bind["type"]=="shadeColor")delta+=bind["targetValue"][0].get<double>()-initial;upper+=std::max(0.,delta);}
 if(std::abs(expected.maximum_shade_coefficient-upper/native)>1e-6||expected.maximum_shade_coefficient<=1.5||scene.encode()!=exact)throw std::runtime_error("Full expression weight-box bound lost simultaneous genuine shade contributions");++passed;
